beforeExample:
package test;
import org.eclipse.jdt.core.dom.*;
public class MyClass {
    public void myMethod(ASTNode selectedNode) {
        if (selectedNode instanceof Name && selectedNode.getParent() instanceof SwitchStatement) {
            System.out.println("Match!");
        }
    }
}

afterExample:
package test;
import org.eclipse.jdt.core.dom.*;
public class MyClass {
    public void myMethod(ASTNode selectedNode) {
        if (selectedNode instanceof Expression && selectedNode.getLocationInParent() == SwitchStatement.EXPRESSION_PROPERTY) {
            System.out.println("Match!");
        }
    }
}

negativeExample:
package test;
import org.eclipse.jdt.core.dom.*;
public class MyClass {
    public void myMethod(ASTNode selectedNode) {
        if (selectedNode instanceof Name && selectedNode.getParent() instanceof Block) {
            System.out.println("No match!");
        }
    }
}
